import{_ as r,o as t,c as a,a5 as s}from"./chunks/framework.CslsFoWx.js";const o="/VendoraSystem-docs/captures/2026-11-05-315-e-reporting/web-01-mois-courant-compteurs-globaux.jpg",i="/VendoraSystem-docs/captures/2026-11-05-315-e-reporting/web-02-septembre-periode-rejetee.jpg",n="/VendoraSystem-docs/captures/2026-11-05-315-e-reporting/web-03-agregats-par-jour-et-taux.jpg",c="/VendoraSystem-docs/captures/2026-11-05-315-e-reporting/web-04-reglages.jpg",p="/VendoraSystem-docs/captures/2026-11-05-315-e-reporting/web-05-retransmission-acceptee.jpg",d="/VendoraSystem-docs/captures/2026-11-05-315-e-reporting/web-06-rien-a-transmettre.jpg",g="/VendoraSystem-docs/captures/2026-11-05-315-e-reporting/web-07-sombre.jpg",h=JSON.parse('{"title":"Lot 3.15 — E-reporting B2C France (05/11/2026)","description":"","frontmatter":{},"headers":[],"relativePath":"preuves/2026-11-05-315-e-reporting.md","filePath":"generated/preuves/2026-11-05-315-e-reporting.md","lastUpdated":null}'),u={name:"preuves/2026-11-05-315-e-reporting.md"};function l(m,e,f,b,j,v){return t(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="lot-3-15-—-e-reporting-b2c-france-05-11-2026" tabindex="-1">Lot 3.15 — E-reporting B2C France (05/11/2026) <a class="header-anchor" href="#lot-3-15-—-e-reporting-b2c-france-05-11-2026" aria-label="Permalink to &quot;Lot 3.15 — E-reporting B2C France (05/11/2026)&quot;">​</a></h1><p class="muted">Dossier <code>docs/captures/2026-11-05-315-e-reporting</code> · 7 image(s) · 0 trace(s)</p><div><p>Spec 12 RG-RPT-24→26, spec 15 RG-FISC-24. Back-office web sur la <strong>vraie stack</strong> : serveur local 8080 (code du lot, migration V71 appliquée au démarrage), back-office <code>ng serve</code> sur 4200 avec le proxy <code>/api</code>, panneau navigateur à 1 280 px (captures rendues à 800 px). Captures en français ; les dictionnaires anglais et arabe sont vérifiés par les tests web (chaque texte des gabarits traduit).</p><p><strong>Données</strong> : commerce de DÉMONSTRATION créé pour le lot — compte fictif <code>epicerie.demo-315@exemple.tn</code>, magasin « Épicerie fine Dupont — Lyon » en euros (module fiscal FR), SIREN fictif <code>123456789</code>, taux de TVA 5,5 / 10 / 20 %, sept produits, <strong>144 ventes</strong> poussées comme par une caisse appairée sur les 40 derniers jours (script <code>demo-315.py</code> du scratchpad, données aléatoires à graine fixe). E-reporting activé en régime réel normal (décades) sur la plateforme simulée, premier jour transmis = il y a 40 jours. Rien n&#39;a été fait sur le commerce réel du serveur.</p><p>Scénario joué par l&#39;API puis à l&#39;écran :</p><ol><li>réglages puis « Transmettre » → <strong>4 transmissions</strong> des périodes échues (21–30/09 avec 18 ventes, puis les trois décades d&#39;octobre), toutes acceptées par la plateforme simulée ;</li><li>rejet simulé de la décade du 21–30/09 (<code>POST /api/v1/dev/e-reporting/transmissions/{id}/reject</code>, motif « Fichier refusé : SIREN inconnu de la plateforme ») ;</li><li>à l&#39;écran : retransmission → révision 2 acceptée ; « Transmettre » → rien à transmettre.</li></ol><table tabindex="0"><thead><tr><th>Capture</th><th>Ce qu&#39;il faut voir</th></tr></thead><tbody><tr><td><code>web-01-mois-courant-compteurs-globaux.jpg</code></td><td>Mois courant (novembre) : bandeau rouge « Transmission rejetée… », rappel du régime, de la plateforme, du SIREN et du premier jour, <strong>compteurs globaux</strong> (1 rejetée sur douze mois, pas seulement le mois affiché), liste « Périodes à traiter » avec la décade de septembre et le motif du rejet, puis les trois décades de novembre « En cours »</td></tr><tr><td><code>web-02-septembre-periode-rejetee.jpg</code></td><td>Septembre (ouvert d&#39;un clic depuis la liste) : décades 1–10 et 11–20 « Avant l&#39;activation · néant », décade 21–30 <strong>« Rejetée »</strong> avec la dernière transmission (initiale · r1, référence <code>SIM-…</code>, motif en rouge), boutons XML et <strong>Retransmettre</strong> ; en dessous, agrégats par jour et par taux</td></tr><tr><td><code>web-03-agregats-par-jour-et-taux.jpg</code></td><td>Agrégats du 26 au 30/09 : par jour, « Clôture scellée » (pas encore : les clôtures journalières du module fiscal se génèrent la nuit), nombre de ventes, puis une ligne par taux (5,5 / 10 / 20 %) avec base HT, TVA et TTC ; note « 26 jour(s) sans vente ce mois-ci »</td></tr><tr><td><code>web-04-reglages.jpg</code></td><td>Réglages (OWNER / ADMIN) : régime de TVA, plateforme agréée (simulée, recette), premier jour transmis, SIREN lu des exports comptables, case « transmettre automatiquement chaque période échue (toutes les heures) », aide sur les vraies plateformes</td></tr><tr><td><code>web-05-retransmission-acceptee.jpg</code></td><td>Après « Retransmettre » : message « Retransmission acceptée (révision 2) », bandeau de rejet disparu, compteurs à 0, période « Acceptée » avec « Retransmission · r2 » et une nouvelle référence de plateforme</td></tr><tr><td><code>web-06-rien-a-transmettre.jpg</code></td><td>Après « Transmettre les périodes échues » : « Rien à transmettre : toutes les périodes échues sont à jour »</td></tr><tr><td><code>web-07-sombre.jpg</code></td><td>Même page en thème sombre</td></tr></tbody></table><p>Vérifié par l&#39;API et le test d&#39;intégration mais pas capturé : transmission « néant » (les décades d&#39;octobre sans vente sont transmises avec <code>&lt;Nil&gt;true&lt;/Nil&gt;</code>), rectification automatique (révision suivante quand une vente arrive après une transmission acceptée), téléchargement du XML (<code>application/xml</code>, nom <code>ereporting-&lt;SIREN&gt;-&lt;début&gt;-&lt;fin&gt;-r&lt;n&gt;.xml</code>), refus pour un magasin hors module FR ou hors euros, journal fiscal (<code>EREPORTING_CONFIG / ACCEPTED / REJECTED</code>).</p></div><h2 id="galerie" tabindex="-1">Galerie <a class="header-anchor" href="#galerie" aria-label="Permalink to &quot;Galerie&quot;">​</a></h2><div class="proof-grid"><figure class="proof"><a href="/VendoraSystem-docs/captures/2026-11-05-315-e-reporting/web-01-mois-courant-compteurs-globaux.jpg" target="_blank"><img src="'+o+'" alt="web-01-mois-courant-compteurs-globaux.jpg" loading="lazy"></a><figcaption>web-01-mois-courant-compteurs-globaux.jpg</figcaption></figure><figure class="proof"><a href="/VendoraSystem-docs/captures/2026-11-05-315-e-reporting/web-02-septembre-periode-rejetee.jpg" target="_blank"><img src="'+i+'" alt="web-02-septembre-periode-rejetee.jpg" loading="lazy"></a><figcaption>web-02-septembre-periode-rejetee.jpg</figcaption></figure><figure class="proof"><a href="/VendoraSystem-docs/captures/2026-11-05-315-e-reporting/web-03-agregats-par-jour-et-taux.jpg" target="_blank"><img src="'+n+'" alt="web-03-agregats-par-jour-et-taux.jpg" loading="lazy"></a><figcaption>web-03-agregats-par-jour-et-taux.jpg</figcaption></figure><figure class="proof"><a href="/VendoraSystem-docs/captures/2026-11-05-315-e-reporting/web-04-reglages.jpg" target="_blank"><img src="'+c+'" alt="web-04-reglages.jpg" loading="lazy"></a><figcaption>web-04-reglages.jpg</figcaption></figure><figure class="proof"><a href="/VendoraSystem-docs/captures/2026-11-05-315-e-reporting/web-05-retransmission-acceptee.jpg" target="_blank"><img src="'+p+'" alt="web-05-retransmission-acceptee.jpg" loading="lazy"></a><figcaption>web-05-retransmission-acceptee.jpg</figcaption></figure><figure class="proof"><a href="/VendoraSystem-docs/captures/2026-11-05-315-e-reporting/web-06-rien-a-transmettre.jpg" target="_blank"><img src="'+d+'" alt="web-06-rien-a-transmettre.jpg" loading="lazy"></a><figcaption>web-06-rien-a-transmettre.jpg</figcaption></figure><figure class="proof"><a href="/VendoraSystem-docs/captures/2026-11-05-315-e-reporting/web-07-sombre.jpg" target="_blank"><img src="'+g+'" alt="web-07-sombre.jpg" loading="lazy"></a><figcaption>web-07-sombre.jpg</figcaption></figure></div>',5)])])}const w=r(u,[["render",l]]);export{h as __pageData,w as default};
